SELECT * FROM (SELECT account_id, CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END AS txn_cohort, COUNT(DISTINCT amount) AS unique_merchants, COUNT(DISTINCT amount) AS unique_accounts FROM transactions GROUP BY account_id, CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) AS sub WHERE unique_accounts < 7
